export default {
	data() {
		return {
			isShowNavBar: false, // 是否需要导航栏
			familyName: '',
			userpwd: '',
			pwdType: 'password'
		};
	},

	onLoad() {
		var pages = getCurrentPages();
		this.isShowNavBar = pages.length > 1;

	},

	methods: {
		inputUsername(e) {
			this.familyName = e.target.value;
		},
		inputPwd(e) {
			this.userpwd = e.target.value;
		},
		delUser() {
			this.familyName = '';
		},
		switchPwd() {
			this.pwdType = this.pwdType === 'text' ? 'password' : 'text';
		},
		login() {
			const familyName = this.familyName,
				userpwd = this.userpwd;

			if (!familyName.trim()) {
				this.$common.toast('请输入账号');
				return;
			}
			if (!userpwd.trim()) {
				this.$common.toast('请输入密码');
				return;
			}
			const params = {
				familyName: familyName,
				password: userpwd
			};
			this.$api({
				url: '/family/login',
				data: params,
				notToken: true
			})
				.then(async res => {
					if(res){
					  this.$store.commit('SETTOKEN', res.token);
					  this.$store.commit('SETUSERINFO', res);
						await this.$common.setStorage('token', res.token);
						await this.$common.setStorage('userInfo', res);
						// 重定向到家庭账户页面
						uni.redirectTo({
							url: '/pages/family/index'
						});
					}

				})
				.catch(e => {
					this.$common.toast(e.msg);
				});
		},
		findPwd() {
			this.$common.toast('暂不支持自助找回密码');
			// uni.navigateTo({
			// 	url: '/pages/findPwd/findPwd'
			// })
		},
		goReg() {
			uni.navigateTo({
				url: '/pages/family/register'
			});
		}
	}
};
